122→/**
123→ * Simple deterministic hash function
124→ * Based on djb2 algorithm — fast, deterministic, good distribution
125→ */
126→function djb2Hash(str) {
127→  let hash = 5381;
128→  for (let i = 0; i < str.length; i++) {
129→    const char = str.charCodeAt(i);
130→    hash = ((hash << 5) + hash) + char; // hash * 33 + char
131→    hash = hash & hash; // Convert to 32-bit integer
132→  }
133→  return Math.abs(hash);
134→}
