 28→export class USDExporter {
 29→  /**
 30→   * Export profile as USDA (ASCII USD format)
 31→   *
 32→   * @param {Object} profile - Complete profile from DeterministicProfileEngine
 33→   * @param {Object} options - Export options
 34→   * @returns {string} Valid USDA content
 35→   */
 36→  static toUSDA(profile, options = {}) {
 37→    // Validate profile before export
 38→    const validation = DeterministicProfileEngine.validateProfile(profile);
 39→    if (!validation.valid) {
 40→      throw new Error(`Invalid profile: ${validation.errors.join(', ')}`);
 41→    }
 42→
 43→    const {
 44→      includeRaw = false,
 45→      referencePath = '/CognitiveSubstrate/Profile',
 46→      indent = '  '
 47→    } = options;
 48→
 49→    const timestamp = new Date().toISOString();
 50→
 51→    let usda = `#usda 1.0
 52→(
 53→    defaultPrim = "TranslatorsProfile"
 54→    doc = "Cognitive profile generated by The Translators interview game"
 55→    customLayerData = {
 56→        string generator = "The Translators v${profile.version || VERSION.profile}"
 57→        string checksum = "${profile.checksum}"
 58→        string anchor = "${profile.anchor}"
 59→        string generated = "${timestamp}"
 60→        string thesis = "USD as Universal State Description"
 61→    }
 62→)
 63→
 64→def "TranslatorsProfile" (
 65→    references = @${referencePath}@
 66→    doc = "Behavioral preferences derived from cognitive interview — overrides base profile"
 67→    kind = "component"
 68→)
 69→{
 70→${this.formatTraits(profile.traits, indent)}
 71→
 72→${this.formatInsights(profile.insights, indent)}
 73→
 74→${this.formatSignalPriority(profile.traits, indent)}
 75→}
 76→`;
 77→
 78→    if (includeRaw) {
 79→      usda += this.formatRawAnswers(profile.raw, indent);
 80→    }
 81→
 82→    return usda;
 83→  }
