 85→  /**
 86→   * Format traits as USD custom attributes
 87→   */
 88→  static formatTraits(traits, indent = '  ') {
 89→    const sortedDims = Object.keys(traits).sort();
 90→    const lines = [`${indent}# === COGNITIVE TRAITS ===`];
 91→
 92→    sortedDims.forEach(dim => {
 93→      const trait = traits[dim];
 94→      lines.push(`${indent}# ${dim.charAt(0).toUpperCase() + dim.slice(1)}`);
 95→      lines.push(`${indent}custom string ${dim} = "${trait.label}"`);
 96→      lines.push(`${indent}custom float ${dim}:score = ${trait.value.toFixed(2)}`);
 97→      lines.push(`${indent}custom string ${dim}:behavior = "${this.escapeString(trait.behavior)}"`);
 98→      lines.push('');
 99→    });
100→
101→    return lines.join('\n');
102→  }
103→
104→  /**
105→   * Format insights as USD custom attributes
106→   */
107→  static formatInsights(insights, indent = '  ') {
108→    const lines = [`${indent}# === COMMUNICATION INSIGHTS ===`];
109→    lines.push(`${indent}custom string[] insights = [`);
110→
111→    insights.forEach((insight, i) => {
112→      const comma = i < insights.length - 1 ? ',' : '';
113→      lines.push(`${indent}${indent}"${this.escapeString(insight)}"${comma}`);
114→    });
115→
116→    lines.push(`${indent}]`);
117→    return lines.join('\n');
118→  }
