182→  /**
183→   * Format raw answers for debugging/transparency
184→   */
185→  static formatRawAnswers(raw, indent = '  ') {
186→    if (!raw || Object.keys(raw).length === 0) return '';
187→
188→    const lines = ['\ndef "RawAnswers" ('];
189→    lines.push(`${indent}doc = "Original interview responses for transparency"`);
190→    lines.push(')');
191→    lines.push('{');
192→
193→    Object.entries(raw).forEach(([questionId, answer]) => {
194→      lines.push(`${indent}custom string ${questionId} = "${answer.value}"`);
195→      lines.push(`${indent}custom float ${questionId}:trait = ${answer.trait}`);
196→      lines.push(`${indent}custom int ${questionId}:depth = ${answer.depth}`);
197→    });
198→
199→    lines.push('}');
200→    return lines.join('\n');
